//! Levels L (hard cases) and O (organic and complex alphabets): original
//! shapes generated by code. Nothing here imitates a specific font.
//!
//! One row of letters per case, 110 px tall, so the layout is the characters
//! of the row. The ground truth (shapes, holes, pieces) comes from the scene;
//! level O also records the irregularity injected.

use kurbo::{BezPath, Point};

use crate::corpus::{CorpusCase, Level, O_IDS};
use crate::degrade::{Degradation, finish};
use crate::error::BenchError;
use crate::organic::{Brush, letter, slice, stroke};
use crate::scene::{Look, Scene, SceneGlyph};
use crate::shapes::{circle, ellipse, polygon, rect};

/// Height of the letters, in pixels.
const CAP: f64 = 110.0;
/// Width of a letter cell.
const CELL_W: f64 = 84.0;
/// Space between cells.
const GAP: f64 = 56.0;
/// Margin of the image.
const MARGIN: f64 = 60.0;
/// Stroke of the crisp letters.
const T: f64 = 16.0;

fn cell_x(i: usize) -> f64 {
    MARGIN + i as f64 * (CELL_W + GAP)
}

fn scene_for(keys: &str) -> Scene {
    let n = keys.chars().count();
    let width = (MARGIN * 2.0 + n as f64 * CELL_W + n.saturating_sub(1) as f64 * GAP).ceil() as u32;
    let height = (MARGIN * 2.0 + CAP).ceil() as u32;
    Scene::new(width, height, vec![keys.to_owned()])
}

fn glyph(key: char, shapes: Vec<BezPath>, x: f64) -> SceneGlyph {
    SceneGlyph {
        key: key.to_string(),
        shapes,
        origin: Some([x, MARGIN + CAP]),
        advance: None,
    }
}

/// A crisp letter drawn with rectangles and ellipses.
fn crisp(ch: char, x: f64, y: f64, w: f64, h: f64) -> Vec<BezPath> {
    match ch {
        'H' => vec![
            rect(x, y, x + T, y + h, true),
            rect(x + w - T, y, x + w, y + h, true),
            rect(
                x + T - 1.0,
                y + h / 2.0 - T / 2.0,
                x + w - T + 1.0,
                y + h / 2.0 + T / 2.0,
                true,
            ),
        ],
        'I' => vec![rect(
            x + w / 2.0 - T / 2.0,
            y,
            x + w / 2.0 + T / 2.0,
            y + h,
            true,
        )],
        'L' => vec![
            rect(x, y, x + T, y + h, true),
            rect(x + T - 1.0, y + h - T, x + w * 0.9, y + h, true),
        ],
        'T' => vec![
            rect(x, y, x + w, y + T, true),
            rect(
                x + w / 2.0 - T / 2.0,
                y + T - 1.0,
                x + w / 2.0 + T / 2.0,
                y + h,
                true,
            ),
        ],
        'E' => vec![
            rect(x, y, x + T, y + h, true),
            rect(x + T - 1.0, y, x + w, y + T, true),
            rect(
                x + T - 1.0,
                y + h / 2.0 - T / 2.0,
                x + w * 0.8,
                y + h / 2.0 + T / 2.0,
                true,
            ),
            rect(x + T - 1.0, y + h - T, x + w, y + h, true),
        ],
        'O' => vec![
            ellipse(x + w / 2.0, y + h / 2.0, w / 2.0, h / 2.0, true),
            ellipse(x + w / 2.0, y + h / 2.0, w / 2.0 - T, h / 2.0 - T, false),
        ],
        _ => Vec::new(),
    }
}

fn crisp_row(keys: &str) -> Scene {
    let mut scene = scene_for(keys);
    for (i, ch) in keys.chars().enumerate() {
        let x = cell_x(i);
        scene
            .glyphs
            .push(glyph(ch, crisp(ch, x, MARGIN, CELL_W, CAP), x));
    }
    scene
}

/// A solid block with one slit (a hole `slit` px wide, at a fractional pixel
/// position so no pixel is entirely background).
fn slit_block(x: f64, slit: f64) -> Vec<BezPath> {
    let (w, y0) = (70.0, MARGIN);
    let sx = x + 31.25;
    vec![
        rect(x, y0, x + w, y0 + CAP, true),
        rect(sx, y0 + 20.0, sx + slit, y0 + CAP - 20.0, false),
    ]
}

fn slit_case(slit: f64) -> Scene {
    let mut scene = crisp_row("HOIL");
    let x = cell_x(1);
    scene.glyphs[1] = glyph('O', slit_block(x, slit), x);
    scene
}

fn small_counter() -> Scene {
    let mut scene = crisp_row("HOIL");
    let x = cell_x(1);
    scene.glyphs[1] = glyph(
        'O',
        vec![
            rect(x, MARGIN, x + 70.0, MARGIN + CAP, true),
            circle(x + 35.0, MARGIN + CAP / 2.0, 2.0, false),
        ],
        x,
    );
    scene
}

fn multi_piece_h() -> Scene {
    let mut scene = crisp_row("HEOL");
    let x = cell_x(0);
    scene.glyphs[0] = glyph(
        'H',
        vec![
            rect(x, MARGIN, x + T, MARGIN + CAP, true),
            rect(x + CELL_W - T, MARGIN, x + CELL_W, MARGIN + CAP, true),
            // The bar floats between the stems.
            rect(
                x + T + 4.0,
                MARGIN + CAP / 2.0 - T / 2.0,
                x + CELL_W - T - 4.0,
                MARGIN + CAP / 2.0 + T / 2.0,
                true,
            ),
        ],
        x,
    );
    scene
}

fn decorative_row() -> Scene {
    let keys = "HLTI";
    let offsets = [0.0, -10.0, 7.0, -4.0];
    let mut scene = scene_for(keys);
    scene.height += 30;
    for (i, ch) in keys.chars().enumerate() {
        let x = cell_x(i);
        let y = MARGIN + 15.0 + offsets[i];
        let mut shapes = crisp(ch, x, y, CELL_W, CAP);
        // Slab serifs on the feet and heads of the stems.
        let (cx, half) = match ch {
            'H' | 'L' => (x + T / 2.0, 15.0),
            _ => (x + CELL_W / 2.0, 15.0),
        };
        shapes.push(rect(cx - half, y + CAP - 6.0, cx + half, y + CAP, true));
        if ch != 'L' {
            shapes.push(rect(cx - half, y, cx + half, y + 6.0, true));
        }
        if ch == 'H' {
            let rx = x + CELL_W - T / 2.0;
            shapes.push(rect(rx - half, y + CAP - 6.0, rx + half, y + CAP, true));
            shapes.push(rect(rx - half, y, rx + half, y + 6.0, true));
        }
        scene.glyphs.push(glyph(ch, shapes, x));
    }
    scene
}

fn touching_pair() -> Scene {
    let mut scene = crisp_row("HEOL");
    // The E overlaps the right stem of the H by two pixels.
    let x = cell_x(0) + CELL_W - 2.0;
    scene.glyphs[1] = glyph('E', crisp('E', x, MARGIN, CELL_W, CAP), x);
    scene
}

fn stray_dot() -> Scene {
    let mut scene = crisp_row("HEOL");
    let x = cell_x(1) + CELL_W + GAP / 2.0;
    scene.extras.push(circle(x, MARGIN + CAP * 0.45, 3.5, true));
    scene
}

fn i_dot() -> Scene {
    let mut scene = scene_for("iHL");
    let x = cell_x(0);
    let cx = x + CELL_W / 2.0;
    scene.glyphs.push(glyph(
        'i',
        vec![
            rect(
                cx - T / 2.0,
                MARGIN + CAP * 0.34,
                cx + T / 2.0,
                MARGIN + CAP,
                true,
            ),
            circle(cx, MARGIN + CAP * 0.1, T * 0.65, true),
        ],
        x,
    ));
    for (i, ch) in "HL".chars().enumerate() {
        let x = cell_x(i + 1);
        scene
            .glyphs
            .push(glyph(ch, crisp(ch, x, MARGIN, CELL_W, CAP), x));
    }
    scene
}

/// A row of organic letters.
fn organic_row(keys: &str, brush: &Brush, pieces: Option<&[(f64, f64)]>) -> Scene {
    let mut scene = scene_for(keys);
    let half = brush.width / 2.0;
    for (i, ch) in keys.chars().enumerate() {
        let x = cell_x(i);
        let mut shapes = Vec::new();
        for (k, skeleton) in letter(
            ch,
            x + half,
            MARGIN + half,
            CELL_W - brush.width,
            CAP - brush.width,
        )
        .into_iter()
        .enumerate()
        {
            let salt = (i * 16 + k) as u64 + 1;
            match pieces {
                None => shapes.extend(stroke(&skeleton, brush, salt)),
                Some(ranges) => {
                    for (r, &(from, to)) in ranges.iter().enumerate() {
                        let part = slice(&skeleton, from, to);
                        shapes.extend(stroke(&part, brush, salt * 8 + r as u64));
                    }
                }
            }
        }
        scene.glyphs.push(glyph(ch, shapes, x));
    }
    scene.irregularity = Some(brush.irregularity());
    scene
}

fn brush(width: f64, seed: u64) -> Brush {
    Brush {
        width,
        pressure: 0.0,
        pressure_cycles: 1.0,
        edge_amp: 0.0,
        edge_wavelength: 8.0,
        wobble: 0.0,
        bulb: None,
        extend: width / 2.0,
        seed,
    }
}

/// A shell with a hole and a core inside it: solid, hole inside solid, solid
/// inside the hole.
fn nested_bar(x0: f64, y0: f64, x1: f64, y1: f64) -> Vec<BezPath> {
    vec![
        rect(x0, y0, x1, y1, true),
        rect(x0 + 4.0, y0 + 4.0, x1 - 4.0, y1 - 4.0, false),
        rect(x0 + 9.0, y0 + 9.0, x1 - 9.0, y1 - 9.0, true),
    ]
}

fn nested_ring(cx: f64, cy: f64, rx: f64, ry: f64) -> Vec<BezPath> {
    vec![
        ellipse(cx, cy, rx, ry, true),
        ellipse(cx, cy, rx - 4.0, ry - 4.0, false),
        ellipse(cx, cy, rx - 9.0, ry - 9.0, true),
        ellipse(cx, cy, rx - 13.0, ry - 13.0, false),
    ]
}

fn inline_outline() -> Scene {
    let keys = "IOB";
    let mut scene = scene_for(keys);
    let (x0, x1, x2) = (cell_x(0), cell_x(1), cell_x(2));
    scene.glyphs.push(glyph(
        'I',
        nested_bar(
            x0 + CELL_W / 2.0 - 13.0,
            MARGIN,
            x0 + CELL_W / 2.0 + 13.0,
            MARGIN + CAP,
        ),
        x0,
    ));
    scene.glyphs.push(glyph(
        'O',
        nested_ring(
            x1 + CELL_W / 2.0,
            MARGIN + CAP / 2.0,
            CELL_W / 2.0,
            CAP / 2.0,
        ),
        x1,
    ));
    let mut b = nested_ring(
        x2 + CELL_W / 2.0,
        MARGIN + CAP * 0.27,
        CELL_W * 0.4,
        CAP * 0.27,
    );
    b.extend(nested_ring(
        x2 + CELL_W / 2.0,
        MARGIN + CAP * 0.73,
        CELL_W * 0.46,
        CAP * 0.27,
    ));
    scene.glyphs.push(glyph('B', b, x2));
    scene.irregularity = Some(0.0);
    scene
}

fn complex_counters() -> Scene {
    let keys = "BEHA";
    let mut scene = scene_for(keys);
    let w = CELL_W;
    let (xb, xe, xh, xa) = (cell_x(0), cell_x(1), cell_x(2), cell_x(3));
    let y = MARGIN;
    // B: two stacked counters.
    scene.glyphs.push(glyph(
        'B',
        vec![
            rect(xb, y, xb + w, y + CAP, true),
            ellipse(xb + w * 0.55, y + CAP * 0.27, w * 0.22, CAP * 0.14, false),
            ellipse(xb + w * 0.55, y + CAP * 0.72, w * 0.26, CAP * 0.16, false),
        ],
        xb,
    ));
    // E: a block with two long slits two pixels high.
    scene.glyphs.push(glyph(
        'E',
        vec![
            rect(xe, y, xe + w, y + CAP, true),
            rect(xe + 18.0, y + 30.0, xe + w - 6.0, y + 32.0, false),
            rect(xe + 18.0, y + 72.0, xe + w - 6.0, y + 74.0, false),
        ],
        xe,
    ));
    // H: a lattice of six windows.
    let mut h = vec![rect(xh, y, xh + w, y + CAP, true)];
    for r in 0..3 {
        for c in 0..2 {
            let (cx0, cy0) = (xh + 10.0 + c as f64 * 36.0, y + 10.0 + r as f64 * 33.0);
            h.push(rect(cx0, cy0, cx0 + 26.0, cy0 + 24.0, false));
        }
    }
    scene.glyphs.push(glyph('H', h, xh));
    // A: a triangle with a small counter.
    let tri = polygon(
        &[
            Point::new(xa + w / 2.0, y),
            Point::new(xa + w, y + CAP),
            Point::new(xa, y + CAP),
        ],
        true,
    );
    let counter = polygon(
        &[
            Point::new(xa + w / 2.0, y + 38.0),
            Point::new(xa + w * 0.64, y + 78.0),
            Point::new(xa + w * 0.36, y + 78.0),
        ],
        false,
    );
    scene.glyphs.push(glyph('A', vec![tri, counter], xa));
    scene.irregularity = Some(0.0);
    scene
}

/// Builds an L or O case.
///
/// # Errors
///
/// [`BenchError::Unknown`] for an unknown id, or any rendering error.
pub fn case(id: &str, level: Level) -> Result<CorpusCase, BenchError> {
    let scene = match id {
        "multi_piece_h" => multi_piece_h(),
        "slit_1px" => slit_case(1.0),
        "slit_2px" => slit_case(2.0),
        "slit_3px" => slit_case(3.0),
        "small_counter" => small_counter(),
        "organic_wobble" => {
            let b = Brush {
                edge_amp: 1.5,
                edge_wavelength: 9.0,
                ..brush(T, 0x1001)
            };
            organic_row("HOIL", &b, None)
        }
        "uneven_light" => {
            let mut s = crisp_row("HEOL");
            s.look = Look {
                light: Some((1.0, 0.55)),
                ..Look::default()
            };
            s
        }
        "decorative_row" => decorative_row(),
        "touching_pair" => touching_pair(),
        "stray_dot" => stray_dot(),
        "i_dot" => i_dot(),
        "hand_pressure" => {
            let b = Brush {
                pressure: 0.35,
                pressure_cycles: 1.5,
                edge_amp: 1.0,
                edge_wavelength: 12.0,
                ..brush(16.0, 0x2001)
            };
            organic_row("HOILTE", &b, None)
        }
        "rough_brush" => {
            let b = Brush {
                pressure: 0.1,
                edge_amp: 2.0,
                edge_wavelength: 3.0,
                ..brush(20.0, 0x2002)
            };
            organic_row("HOILTE", &b, None)
        }
        "ink_bleed" => {
            let b = Brush {
                edge_amp: 0.8,
                edge_wavelength: 6.0,
                ..brush(16.0, 0x2003)
            };
            let mut s = organic_row("HOILTE", &b, None);
            s.look.bleed = true;
            s
        }
        "bulb_organic" => {
            let b = Brush {
                bulb: Some((1.3, 1.5)),
                wobble: 1.2,
                ..brush(12.0, 0x2004)
            };
            organic_row("HILTE", &b, None)
        }
        "stencil" => {
            let b = Brush {
                edge_amp: 0.4,
                edge_wavelength: 7.0,
                extend: 0.0,
                ..brush(18.0, 0x2005)
            };
            organic_row(
                "HOILTE",
                &b,
                Some(&[(0.02, 0.30), (0.38, 0.64), (0.72, 0.97)]),
            )
        }
        "inline_outline" => inline_outline(),
        "complex_counters" => complex_counters(),
        other => return Err(BenchError::Unknown(format!("hard case {other:?}"))),
    };
    debug_assert!(level != Level::O || O_IDS.contains(&id));
    let layout = scene.layout.clone();
    let (image, extension, truth) = finish(scene, Degradation::None)?;
    Ok(CorpusCase {
        id: id.to_owned(),
        level,
        image,
        extension,
        layout,
        truth: Some(truth),
    })
}
